#!/usr/bin/env python3
import sys, math, fractions, itertools, collections


def solve(n: int, v: "List[int]"):
    o = v[1::2]
    e = v[::2]
    oc = collections.Counter(o).most_common()
    ec = collections.Counter(e).most_common()
    if len(oc) > 1:
        om1, om2 = oc[0], oc[1]
    else:
        om1, om2 = oc[0], (-1, 0)
    if len(ec) > 1:
        em1, em2 = ec[0], ec[1]
    else:
        em1, em2 = ec[0], (-1, 0)
    if om1[0] != em1[0]:
        print(n - om1[1] - em1[1])
    else:
        print(min(n-om1[1]-em2[1], n-om2[1]-em1[1]))
    return


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    n = int(next(tokens))  # type: int
    v = [ int(next(tokens)) for _ in range(n) ]  # type: "List[int]"
    solve(n, v)

if __name__ == '__main__':
    main()
